'use strict';
// Use FOSSGIS's dedicated foot graph and validated walking-mode results.
const V17WALK={nextAt:0,queue:Promise.resolve(),memory:new Map()};
function v17WalkKey(coords){return coords.map(c=>[Number(c.lon.toFixed(6)),Number(c.lat.toFixed(6))].join(',')).join(';')}
function v17WalkDirections(step){const m=step.maneuver||{},mod={'left':'左转','right':'右转','slight left':'向左前方','slight right':'向右前方','sharp left':'向左后方','sharp right':'向右后方','straight':'直行','uturn':'掉头'},action=m.type==='depart'?'开始步行':m.type==='arrive'?'到达路径终点':m.type==='roundabout'?'沿环岛行走':mod[m.modifier]||'沿路前行';return action+(step.name?' · '+step.name:' · 步道或未命名路段')}
function v17WalkingPlan(plan,route,waypoints=[],basis='live',fetchedAt=new Date().toISOString()){const coordinates=route.geometry?.coordinates;if(!Array.isArray(coordinates)||coordinates.length<2||!coordinates.every(c=>Array.isArray(c)&&c.length>=2&&c.slice(0,2).every(Number.isFinite))||!Number.isFinite(route.distance)||route.distance<0||!Number.isFinite(route.duration)||route.duration<0)throw Error('步行服务没有有效路径、距离或时长');const steps=route.steps||(route.legs||[]).flatMap(l=>l.steps||[]);if(steps.some(s=>s.mode&&s.mode!=='walking'))throw Error('服务返回包含非步行区段的方案，未作为纯步行路线');if(waypoints.some(w=>!Number.isFinite(w.distance)||w.distance>150))throw Error('输入地点距离步行路网接入点过远，请选择具体入口或邻近道路');return {...plan,geometry:route.geometry,geometryBasis:'current-reference',distance:route.distance,duration:route.duration,durationBasis:'当前步行路网与正常步行速度参考',arrivalText:plan.mode==='history'?'历史灾时到达时间未取得':'正常步行条件下参考，非实际到达承诺',roadNames:route.roadNames||[...new Set(steps.map(s=>s.name).filter(Boolean))],walkSteps:steps.map(s=>({name:s.name||'',distance:s.distance||0,duration:s.duration||0,instruction:v17WalkDirections(s)})),walkSnaps:waypoints.map(w=>({lat:w.location?.[1],lon:w.location?.[0],distance:w.distance})),routeProvider:'FOSSGIS/OSRM · foot graph',routeFetchedAt:fetchedAt,routeSource:'https://routing.openstreetmap.de/about.html',label:basis==='cache'?'已缓存2026-10-13步行路网参考 · 不含实时积水与封路':plan.mode==='history'?'当前步行路网参考 · 不是2023灾时路线或时长':'FOSSGIS步行路径参考 · 不含实时积水与封路',unavailable:false}}
async function v17BuildWalkingLeg(plan,coords,seq){const key=v17WalkKey(coords),memo=V17WALK.memory.get(key);if(memo&&Date.now()-memo.fetched<15*60000)return v17WalkingPlan(plan,memo.route,memo.waypoints,'live',memo.fetchedAt);const task=async()=>{if(seq!==V2.requestSeq)return {...plan,unavailable:true,label:'查询已取消，未写入旧路线'};const wait=Math.max(0,V17WALK.nextAt-Date.now());if(wait)await new Promise(resolve=>setTimeout(resolve,wait));if(seq!==V2.requestSeq)return {...plan,unavailable:true,label:'查询已取消，未写入旧路线'};V17WALK.nextAt=Date.now()+1050;try{const url=`https://routing.openstreetmap.de/routed-foot/route/v1/foot/${key}?overview=full&geometries=geojson&steps=true&generate_hints=false`,response=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!response.ok)throw Error('步行服务暂未返回');const out=await response.json();if(out.code!=='Ok'||!out.routes?.length)throw Error(out.code==='NoRoute'?'这些地点之间暂未取得连通步行路径':'步行服务没有可用结果');const route=out.routes[0],at=new Date().toISOString(),result=v17WalkingPlan(plan,route,out.waypoints||[],'live',at);V17WALK.memory.set(key,{route,waypoints:out.waypoints||[],fetched:Date.now(),fetchedAt:at});return result}catch(err){const cached=(window.WALK_ROUTE_CACHE||[]).find(r=>r.coords.map(c=>c.join(',')).join(';')===key);if(cached)return v17WalkingPlan(plan,cached.route,cached.waypoints,'cache',cached.fetchedAt);return {...plan,unavailable:true,label:(err.message||'步行路线查询失败')+'；没有沿用驾车路线或直线',geometry:null,distance:null,duration:null}}};const promise=V17WALK.queue.then(task,task);V17WALK.queue=promise.then(()=>{},()=>{});return promise}
function v17WalkDetail(p){if(p.transport!=='步行'||!p.geometry)return '';const snaps=p.walkSnaps||[],offsets=snaps.filter(s=>s.distance>=30);return `<details class="v17walkdetail"><summary>步行路段、接入点与来源</summary><p>沿当前公开步行路网查询。${p.mode==='history'?'时长仅是正常条件下参考，无法证明历史暴雨期间可通行。':'时长按路由服务的正常步行条件估算，没有实时积水或封路输入。'}</p>${offsets.length?`<p>原始地点为站点或建筑参考位置，路径从邻近路网接入；接入偏移 ${offsets.map(s=>Math.round(s.distance)+'米').join('、')}，不绘制假设连接线。</p>`:''}<ol>${(p.walkSteps||[]).slice(0,80).map(s=>`<li>${esc(s.instruction)}${s.distance?' · '+Math.round(s.distance)+'米':''}</li>`).join('')}</ol><small>查询／缓存时间：${esc(Number.isFinite(Date.parse(p.routeFetchedAt))?dateText(new Date(p.routeFetchedAt).toISOString()):'查询时刻未记录')}</small><p><a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener">FOSSGIS路由服务与数据说明 ↗</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">反馈地图问题 ↗</a> · © OpenStreetMap contributors</p></details>`}
